from pathlib import Path
import json, base64, html, struct, runpy

BUILD=Path(__file__).resolve().parent
ROOT=BUILD.parents[2]
OUT=BUILD.parent/'output'
OUT.mkdir(exist_ok=True)
D=json.loads((BUILD/'content.json').read_text(encoding='utf-8'))
E=ROOT/'docs/evidence/dashboard-english'
C=BUILD/'captures'
def esc(t): return html.escape(str(t))
def uri(p): return 'data:image/png;base64,'+base64.b64encode(Path(p).read_bytes()).decode('ascii')
def dims(p):
    with open(p,'rb') as f: return struct.unpack('>II',f.read(24)[16:24])
def shot(path,caption,crop=None,marks=(),cls=''):
    w,h=dims(path)
    x,y,cw,ch=crop or (0,0,w,h)
    imstyle=f'width:{w/cw*100:.5f}%;left:{-x/cw*100:.5f}%;top:{-y/ch*100:.5f}%;'
    overlay=''
    for label,bx,by,bw,bh in marks:
        overlay+=f'<span class="mark" style="left:{(bx-x)/cw*100:.3f}%;top:{(by-y)/ch*100:.3f}%;width:{bw/cw*100:.3f}%;height:{bh/ch*100:.3f}%"><b>{esc(label)}</b></span>'
    return f'<figure class="shot {cls}"><div class="imageview" tabindex="0" role="button" aria-label="Phóng to ảnh {esc(caption)}" style="aspect-ratio:{cw}/{ch}"><img alt="{esc(caption)}" src="{uri(path)}" style="{imstyle}">{overlay}</div><figcaption>{esc(caption)}</figcaption></figure>'

