def bullets(s):return '<ul>'+''.join('<li>'+esc(b)+'</li>' for b in s['bullets'])+'</ul>'
def visual(n):
    if n==1:
        pic=shot(E/'workspace-1-desktop.png','Workspace trong bộ ảnh kiểm chứng • vùng hero, ảnh thật từ replay',(65,55,1470,415))
        return f'<div class="bodygrid reverse"><div class="summary">{bullets(D["slides"][0])}<p class="caution">Chỉ đánh giá dashboard. Không suy ra mô hình chính xác hơn hoặc pipeline nhanh hơn.</p></div><div style="padding-top:22px">{pic}<p class="stamp">Hình kính là trang trí. RUNNING trong ảnh là trạng thái đã lưu.</p></div></div>'
    if n==2:
        pic=shot(E/'baseline-1-desktop.png','Control Room gốc • vùng nội dung được phóng to từ ảnh replay',(325,190,1210,870),[(1,336,206,1184,246),(2,336,729,1184,310)])
        return f'<div class="bodygrid">{pic}<div class="summary">{bullets(D["slides"][1])}<p class="caution">Snapshot minh họa: 5.200 đã phát, 4.700 đã xử lý, 500 đang chờ. Không phải kết quả tăng tốc.</p></div></div>'
    if n==3:
        pic=shot(E/'baseline-4-desktop.png','Bản gốc • bảng giao dịch trong cửa sổ dữ liệu gần nhất',(325,650,1210,450),[(1,336,733,1184,365)])
        return f'<div style="flex:1"><div style="max-width:1030px;margin:auto">{pic}</div><div class="pair" style="margin-top:20px;font-size:25px"><div><strong>Tình huống minh họa</strong><p>TRANSFER, số tiền lớn, đang có cảnh báo. Cần đối chiếu nhiều cột.</p></div><div><strong>Khoảng trống trong luồng thao tác</strong><p>Chưa có bộ lọc kết hợp và inspector theo Event ID riêng.</p></div></div></div>'
    if n==4:
        rows=[('Nhiều nội dung nối tiếp','Phải tìm vùng cần chú ý','Nhóm nội dung, mở chi tiết khi cần'),('Đối chiếu nhiều cột','Khó tập trung đúng giao dịch','Lọc kết hợp, xem chi tiết theo ID'),('KPI tổng và cửa sổ gần nhất','Có thể hiểu sai phạm vi','Ghi rõ phạm vi và trạng thái rỗng')]
        r=''.join('<div class="flowrow"><span>'+esc(a)+'</span><span class="arrow">→</span><span>'+esc(b)+'</span><span class="arrow">→</span><span>'+esc(c)+'</span></div>' for a,b,c in rows)
        return '<div class="flow"><div class="flowhead"><span>Hạn chế</span><span></span><span>Ảnh hưởng kỳ vọng</span><span></span><span>Mục tiêu cải tiến</span></div>'+r+'<p class="flow-caption">Sơ đồ phân tích tác vụ do bài trình bày tổng hợp. Không phải kết quả khảo sát hay số liệu đo hiệu quả.</p><div class="flow-bottom"><p><strong>Giữ nguyên</strong><br>Công thức chỉ số và kết quả mô hình.</p><p><strong>Cần đánh giá</strong><br>Khả năng tìm và hiểu thông tin trong từng tác vụ.</p></div></div>'
    if n==5:
        p1=shot(C/'workspace-overview-charts.png','1 • Vùng biểu đồ vận hành sau khi cuộn; replay theo mã hiện tại',(65,65,1470,920),[(1,71,90,1010,850)])
        p2=shot(C/'workspace-business-comparison.png','2 • Thanh so sánh rule–model; chỉ thay cách trình bày',(65,115,1470,430),[(2,72,130,850,385)])
        return f'<div class="bodygrid wide"><div class="newvisual"><div class="two-shots">{p1}{shot(C/"workspace-metrics-default.png","Các nhóm chỉ số có thể mở/thu gọn",(65,125,1470,920))}</div>{p2}</div><div class="summary" style="font-size:23px">{bullets(D["slides"][4])}<p class="caution">Thu gọn giảm nội dung mở cùng lúc, đổi lấy thêm lần bấm. Lợi ích về tốc độ đọc chưa đo.</p></div></div>'
    if n==6:
        p1=shot(C/'workspace-transactions-filters.png','1 • Bộ lọc thật trên 60 giao dịch đã nạp',(68,195,1465,390),[(1,71,202,1457,375)])
        p2=shot(C/'workspace-transaction-result-and-details.png','2 • Một ID có thật: vùng chọn, nút CSV và chi tiết giao dịch',(68,330,1465,550),[(2,71,333,1457,535)])
        return f'<div class="bodygrid"><div class="newvisual">{p1}{p2}</div><div class="summary" style="font-size:23px">{bullets(D["slides"][5])}<p class="caution">KPI toàn run không đổi. Lọc risk score không đổi ngưỡng. Alert là dự đoán, chưa xác nhận gian lận.</p></div></div>'
    if n==7:
        p1=shot(E/'baseline-1-desktop.png','Cũ • Control Room gốc, 1600 × 1100',marks=[('Biểu đồ',336,729,1184,310)])
        p2=shot(E/'workspace-1-desktop.png','Mới • Workspace trong bộ ảnh đối chiếu, 1600 × 1100',marks=[('Hero',71,110,1458,352),('KPI',71,574,1458,376)])
        rows=[('Thao tác giao dịch','Bảng và công cụ gốc','Bộ lọc kết hợp, chi tiết ID, CSV theo tập lọc'),('Chi tiết vận hành','Nhiều nội dung mở trực tiếp','Thu gọn nhiều phần, cần bấm thêm'),('Hiệu năng','Tự làm mới 2 giây','Giữ truy vấn lõi, chưa chứng minh nhanh hơn')]
        table='<table class="mini"><tr><th>Tiêu chí</th><th>Cũ</th><th>Mới và đánh đổi</th></tr>'+''.join('<tr>'+''.join('<td>'+esc(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</table>'
        return f'<div class="comparison-visual"><div class="pair">{p1}{p2}</div>{table}<p style="font-size:18px;margin:13px 0;color:#5e6874">Cùng snapshot. Sáu KPI khớp trên bốn cặp trang trong bằng chứng lưu. Không có benchmark render hoặc tác vụ.</p></div>'
    if n==8:
        p2=shot(E/'workspace-1-mobile.png','Workspace • 390 × 844 • ảnh replay')
        return f'<div class="bodygrid finalgrid"><div><div class="mobilepair">{p2}</div><p style="font-size:18px;line-height:1.35">Không tràn ngang cấp trang trong phạm vi kiểm thử. Chưa đánh giá mọi tác vụ trên mobile.</p></div><div class="summary">{bullets(D["slides"][7])}<p class="caution">Các hướng tiếp theo là đề xuất. Chưa có kết quả đo hiệu quả người dùng.</p></div></div>'

sections=[]
for s in D['slides']:
    n=s['n']; main=visual(n)
    foot='Ảnh thật từ snapshot replay • Chú thích được phủ lên ảnh, không thay số liệu.' if n!=4 else 'Sơ đồ phân tích • Tình huống minh họa và lợi ích kỳ vọng chưa được đo.'
    if n in (5,6): foot+=' Nhãn điều hướng trong mã hiện tại khác bộ ảnh dashboard-english.'
    canvas=f'<div class="stage"><section class="canvas" aria-label="Slide {n}"><header class="slidehead"><h2>{esc(s["title"])}</h2><span class="slideno">{n:02d} / 08 · {s["seconds"]} giây</span></header><p class="message">{esc(s["message"])}</p>{main}<footer class="slidefoot">{foot}</footer></section></div>'
    notes=f'<section class="notes"><button class="copy" data-copy="{n}">Sao chép lời nói</button><h3>Lời thoại dùng trực tiếp</h3><p class="spoken">{esc(s["speech"])}</p><h3>Lời nói khi chỉ hình</h3><p class="spoken">{esc(s["point"])}</p><h3>Câu chuyển</h3><p class="spoken">{esc(s["transition"])}</p><p class="status"><strong>Mức độ bằng chứng:</strong> {esc(s["status"])}</p><p class="source"><strong>Nguồn:</strong> {esc("; ".join(s["sources"]))}</p></section>'
    sections.append(f'<article id="slide-{n}" data-index="{n-1}" class="{"active" if n==1 else ""}">{canvas}{notes}</article>')

def table(headers,rows,cls=''):
    return '<table class="'+cls+'"><thead><tr>'+''.join('<th>'+esc(t)+'</th>' for t in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table>'
compare=table(['Tiêu chí','Dashboard cũ','Workspace mới','Hạn chế và đánh đổi'],D['comparison'])
qa=''.join(f'<section class="qa"><h3>{i}. {esc(q["q"])}</h3><p>{esc(q["a"])}</p></section>' for i,q in enumerate(D['qa'],1))
plan=table(['Tác vụ','Thiết kế đánh giá đề xuất','Chỉ số cần ghi nhận'],D['evaluation'],'plan')
sources='''<ol class="source-list"><li><strong>Phiên bản:</strong> dashboard/app.py, dashboard/dashboard_core.py, dashboard/view_workspace.py, dashboard/ui_theme.py, dashboard/ui_pages.py và dashboard/ui_transactions.py. Checkpoint 03ac9a5 là mốc trước redesign, đã chứa các phương án lịch sử.</li><li><strong>Ảnh cặp trước–sau:</strong> docs/evidence/dashboard-english/baseline-*.png và workspace-*.png. Bộ ảnh desktop 1600 × 1100, mobile 390 × 844.</li><li><strong>Kiểm chứng lưu trong dự án:</strong> docs/evidence/dashboard-english/browser-results.json và verification.md. Kết quả ghi nhận 34 passed, 12 skipped, 12 subtests passed. Đây là kết quả đã lưu, không phải tuyên bố vừa chạy lại toàn bộ kiểm thử.</li><li><strong>Ảnh bổ sung từ mã hiện tại:</strong> artifacts/dashboard-presentation-20261029/build/captures/. Chụp biểu đồ, nhóm chỉ số, bộ lọc, CSV và chi tiết theo Event ID bằng snapshot replay trong bộ nhớ. Nguồn snapshot là docs/evidence/dashboard-ui/snapshot.json, run run-20261023-155039. Event ID thực được chọn: run-20261023-155039-c001-e000000004201. Chỉ tìm theo ID, không áp dụng tình huống lọc TRANSFER minh họa. Metadata chụp lưu ở build/captures/capture-metadata.json.</li><li><strong>Chuyển động:</strong> docs/evidence/dashboard-motion/results.json xác nhận hành vi refresh, tạm dừng ngoài màn hình, giảm chuyển động và không cần WebGL. Không có số đo FPS/CPU hoặc hiệu quả nghiệp vụ.</li><li><strong>Tài liệu đối chiếu:</strong> docs/05_Huong_Dan_Cai_Tien_Dashboard.md, docs/07_Dashboard_Pastel_Redesign.md, docs/08_Bao_Cao_Ket_Qua_Toi_Uu_Du_An.md và báo cáo DOCX hiện có. Khi mô tả khác với mã/ảnh, bài ưu tiên mã và bằng chứng trực tiếp. Vì vậy không gọi bản cũ là tĩnh và không coi so sánh mô hình hay confusion matrix là tính năng hoàn toàn mới.</li></ol>'''
timeline=table(['Slide','Phần trình bày','Dự kiến'],[[str(s['n']),s['title'],str(s['seconds'])+' giây'] for s in D['slides']])
intro=f'<section class="intro"><h1>{esc(D["title"])}</h1><p>{esc(D["subtitle"])}. Tám slide, thời lượng dự kiến <strong>{esc(D["duration"])}</strong>, chưa gồm hỏi đáp.</p><p><strong>Cách dùng:</strong> đọc lời thoại dưới mỗi slide. Bấm <strong>Trình chiếu</strong> để chỉ hiện slide, dùng phím ← → để chuyển, F để toàn màn hình, S để trở về kịch bản. Bấm ảnh để phóng to. Tệp đã nhúng ảnh, không cần Internet.</p><p class="scope"><strong>Phạm vi phiên bản:</strong> {esc(D["basis"])}</p><p class="scope"><strong>Giới hạn bằng chứng:</strong> {esc(D["disclosure"])}</p><nav class="toc">'+''.join(f'<a href="#slide-{s["n"]}">{s["n"]}. {esc(s["title"])}</a>' for s in D['slides'])+'<a href="#comparison">Bảng đầy đủ</a><a href="#questions">Câu hỏi phản biện</a></nav></section>'
appendix=f'<section class="appendix" id="comparison"><h2>Bảng so sánh đầy đủ</h2><p>Phụ lục tham khảo, không cần đọc hết trong 6 phút 30 giây. Nhận định về độ thuận tiện là phân tích hoặc kỳ vọng nếu chưa có phép đo.</p>{compare}<h2 id="questions">Năm câu hỏi phản biện</h2>{qa}<h2>Kế hoạch đánh giá đề xuất</h2><p>Dùng cùng snapshot và cùng thiết bị. Cho người tham gia làm cùng tác vụ trên cả hai bản, đổi thứ tự phiên bản để giảm ảnh hưởng làm quen. Ghi điều kiện thử và lặp lại để báo cáo độ phân tán, không chỉ giá trị trung bình. Chưa đặt mục tiêu phần trăm cải thiện khi chưa có số đo gốc.</p>{plan}<h2>Phân bổ thời gian dự kiến</h2>{timeline}<p class="small">Tổng 390 giây. Thời lượng gồm lời thoại, lời nói khi chỉ hình và câu chuyển. Nên diễn tập một lần để điều chỉnh khoảng ngừng theo tốc độ nói.</p><h2>Nguồn và phạm vi kiểm chứng</h2>{sources}</section>'
JS='''
let current=0;const articles=[...document.querySelectorAll('article')];const slides=articles.length;const counter=document.querySelector('.counter');
function scale(){for(const a of articles){const st=a.querySelector('.stage');const width=document.body.classList.contains('deck')?Math.min(window.innerWidth-20,(window.innerHeight-82)*1440/810):Math.min(a.clientWidth,1440);const z=width/1440;st.style.width=width+'px';st.style.height=810*z+'px';st.style.setProperty('--zoom',z)}}
function activate(i){current=Math.max(0,Math.min(slides-1,i));articles.forEach((a,j)=>a.classList.toggle('active',j===current));counter.textContent=(current+1)+' / '+slides;scale()}
function deck(on){document.body.classList.toggle('deck',on);document.getElementById('mode').textContent=on?'Đọc kịch bản':'Trình chiếu';activate(current);if(!on)articles[current].scrollIntoView({behavior:'instant'});else window.scrollTo(0,0)}
document.getElementById('mode').onclick=()=>deck(!document.body.classList.contains('deck'));document.getElementById('prev').onclick=()=>{activate(current-1);if(!document.body.classList.contains('deck'))articles[current].scrollIntoView()};document.getElementById('next').onclick=()=>{activate(current+1);if(!document.body.classList.contains('deck'))articles[current].scrollIntoView()};document.getElementById('full').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();document.getElementById('print').onclick=()=>window.print();
const modal=document.querySelector('.modal');const mc=document.querySelector('.modal-content');let lastFocus=null;function closeModal(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true');if(lastFocus)lastFocus.focus()}function openShot(el){lastFocus=el;mc.innerHTML='';mc.append(el.closest('figure').cloneNode(true));modal.classList.add('open');modal.setAttribute('aria-hidden','false');modal.querySelector('.close').focus()}
document.querySelectorAll('.imageview').forEach(el=>{el.onclick=()=>openShot(el);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openShot(el)}}});modal.querySelector('.close').onclick=closeModal;modal.onclick=e=>{if(e.target===modal)closeModal()};
document.addEventListener('keydown',e=>{if(modal.classList.contains('open')){if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='Tab'){e.preventDefault();modal.querySelector('.close').focus()}return}if(e.ctrlKey||e.metaKey||e.altKey)return;if(e.key.toLowerCase()==='s'){e.preventDefault();deck(false)}if(e.key.toLowerCase()==='f'){e.preventDefault();document.getElementById('full').click()}if(document.body.classList.contains('deck')){if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();activate(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();activate(current-1)}if(e.key==='Home'){e.preventDefault();activate(0)}if(e.key==='End'){e.preventDefault();activate(slides-1)}if(e.key==='Escape'&&!document.fullscreenElement)deck(false)}});
document.querySelectorAll('.toc a[href^="#slide-"]').forEach(a=>a.onclick=()=>activate(Number(a.hash.split('-')[1])-1));document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{const text=[...b.parentNode.querySelectorAll('.spoken')].map(p=>p.textContent).join('\\n\\n');try{await navigator.clipboard.writeText(text);b.textContent='Đã sao chép';setTimeout(()=>b.textContent='Sao chép lời nói',1600)}catch(e){b.textContent='Chọn lời thoại để sao chép'}});window.addEventListener('resize',scale);window.addEventListener('beforeprint',()=>{document.body.classList.remove('deck');document.querySelectorAll('.stage').forEach(st=>{const z=650/1440;st.style.width='650px';st.style.height=(810*z)+'px';st.style.setProperty('--zoom',z)})});window.addEventListener('afterprint',scale);activate(0);
'''
CSS+='\n.comparison-visual .pair{max-width:860px}.comparison-visual .imageview{height:auto;aspect-ratio:1600/1100!important}.mobilepair .shot{width:220px}'
htmlout='<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><title>'+esc(D['title'])+' — kịch bản và trình chiếu</title><style>'+CSS+'</style></head><body><div class="toolbar"><strong>PaySim · Tối ưu dashboard</strong><button id="mode" class="primary">Trình chiếu</button><button id="prev" aria-label="Slide trước">←</button><span class="counter">1 / 8</span><button id="next" aria-label="Slide tiếp theo">→</button><button id="full">Toàn màn hình</button><button id="print" class="print">In kịch bản</button><span class="help">← → chuyển slide · S đọc · F toàn màn hình</span></div><main>'+intro+''.join(sections)+appendix+'</main><div class="modal" role="dialog" aria-modal="true" aria-label="Ảnh phóng to" aria-hidden="true"><button class="close">Đóng ảnh ×</button><div class="modal-content"></div></div><script>'+JS+'</script></body></html>'
(OUT/'Thuyet_trinh_toi_uu_dashboard_PaySim.html').write_text(htmlout,encoding='utf-8')
runpy.run_path(str(BUILD/'embed_speaker_script.py'), run_name='__main__')
runpy.run_path(str(BUILD/'enable_inline_notes.py'), run_name='__main__')
runpy.run_path(str(BUILD/'update_running_presentation.py'), run_name='__main__')

md=['# '+D['title'],'',D['subtitle']+'. **8 slide · Dự kiến '+D['duration']+' · Chưa gồm hỏi đáp.**','',D['basis'],'',D['disclosure'],'','Bản HTML cùng thư mục nhúng đầy đủ ảnh và chú thích, có chế độ trình chiếu và phóng to. Bản Markdown này thuận tiện chỉnh lời thoại.','']
for s in D['slides']:
    md+=['## Slide '+str(s['n'])+' · '+s['title']+' · '+str(s['seconds'])+' giây','','**Thông điệp chính:** '+s['message'],'','**Nội dung trên slide**','']+['- '+b for b in s['bullets']]+['','**Lời thoại dùng trực tiếp**','',s['speech'],'','**Lời nói khi chỉ hình**','',s['point'],'','**Câu chuyển**','',s['transition'],'','**Bằng chứng:** '+s['status'],'','**Nguồn:** '+'; '.join(s['sources']), '']
md+=['## Bảng so sánh đầy đủ','','| Tiêu chí | Cũ | Mới | Hạn chế và đánh đổi |','| --- | --- | --- | --- |']+['| '+' | '.join(row)+' |' for row in D['comparison']]+['','## Năm câu hỏi phản biện','']
for i,q in enumerate(D['qa'],1):md+=['### '+str(i)+'. '+q['q'],'',q['a'],'']
md+=['## Kế hoạch đánh giá đề xuất','','Dùng cùng snapshot, cùng thiết bị và cùng tác vụ. Đổi thứ tự phiên bản để giảm hiệu ứng làm quen. Chưa đặt tỷ lệ cải thiện khi chưa có số đo gốc.','','| Tác vụ | Thiết kế đánh giá | Cần ghi nhận |','| --- | --- | --- |']+['| '+' | '.join(row)+' |' for row in D['evaluation']]+['','Ảnh và sơ đồ thực sự được nhúng trong bản HTML. Các hình so sánh dùng cùng snapshot ngày 23/10/2026. Ảnh bổ sung dùng replay theo mã hiện tại, không ghi cơ sở dữ liệu nguồn.','']
(OUT/'Kich_ban_toi_uu_dashboard_PaySim.md').write_text('\n'.join(md),encoding='utf-8')
print(json.dumps({'html_bytes':len(htmlout.encode()),'slides':len(D['slides']),'seconds':sum(s['seconds'] for s in D['slides']),'output':str(OUT)},ensure_ascii=False))
